"""ONE CORE mechanical/support assessment. No human fitting, IK or body-clearance pass."""
from pathlib import Path
import os,json,hashlib,subprocess
ROOT=Path(os.environ['C2_OUT']);DEV=os.environ.get('TEST_DEVICE','desktop');OUT=ROOT/'settlement';SITE=ROOT/'settlement-site'
# Works on the new actual host captures; optional old artifact for red reproduction.
down=OUT/(DEV+'_h4_down.json');up=OUT/(DEV+'_h4_up.json')
if not down.exists() or not up.exists():raise RuntimeError('CURRENT_CAPTURE_REQUIRED')
program=r'''
const fs=require('fs'),crypto=require('crypto'),path=require('path');global.window=global;
const [site,downPath,upPath]=process.argv.slice(1);require(path.join(site,'runtime.js'));const T=ATLASRuntime;
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const raw=fs.readFileSync(path.join(site,'assets/ATLAS_Bay_Play.glb'));if(hash(raw)!=='b1ef9c448309a9a5d85ec4f2efcf45d9406d999ab24d27bdd1534359a7278b82')throw Error('MODEL_HASH');
const len=raw.readUInt32LE(12),doc=JSON.parse(raw.subarray(20,20+len)),bin=raw.subarray(28+len),parents=new Map();doc.nodes.forEach((n,i)=>(n.children||[]).forEach(c=>parents.set(c,i)));
const down=JSON.parse(fs.readFileSync(downPath)),up=JSON.parse(fs.readFileSync(upPath)),sourceSet=JSON.parse(fs.readFileSync(path.join(site,'c2-h6-source-set.json'))),contacts=JSON.parse(fs.readFileSync(path.join(site,'c2-contacts.json')));
function acc(i){const a=doc.accessors[i],b=doc.bufferViews[a.bufferView],width={SCALAR:1,VEC3:3,VEC4:4}[a.type],bytes={5126:4,5123:2,5125:4}[a.componentType],read={5126:'readFloatLE',5123:'readUInt16LE',5125:'readUInt32LE'}[a.componentType],v=[];for(let j=0;j<a.count;j++)for(let k=0;k<width;k++)v.push(bin[read]((b.byteOffset||0)+(a.byteOffset||0)+j*(b.byteStride||width*bytes)+k*bytes));return v;}
function local(i,angle=0){const n=doc.nodes[i];if(n.matrix)return new T.Matrix4().fromArray(n.matrix);return new T.Matrix4().compose(new T.Vector3().fromArray(n.translation||[0,0,0]),[145,150].includes(i)?new T.Quaternion().setFromAxisAngle(new T.Vector3(0,0,1),angle):new T.Quaternion().fromArray(n.rotation||[0,0,0,1]),new T.Vector3().fromArray(n.scale||[1,1,1]));}
function rest(i,angle=0){return parents.has(i)?rest(parents.get(i),angle).multiply(local(i,angle)):local(i,angle);}
function geometry(i){const node=doc.nodes[i],p=doc.meshes[node.mesh]['primitives'][0],positions=acc(p.attributes.POSITION),indices=acc(p.indices);return {positions,indices};}
const cache=new Map();function verts(i,m=rest(i)){if(!cache.has(i))cache.set(i,geometry(i));const g=cache.get(i),v=[];for(let j=0;j<g.positions.length;j+=3)v.push(new T.Vector3(...g.positions.slice(j,j+3)).applyMatrix4(m));return v;}
const box=vs=>{const b=new T.Box3().setFromPoints(vs);return {min:b.min.toArray(),max:b.max.toArray(),size:b.getSize(new T.Vector3()).toArray()};};
const records=[];for(const i of [138,137,81,139,147,148]){const a=down.sources.find(s=>s.originalNodeIndex===i),b=up.sources.find(s=>s.originalNodeIndex===i);if(!a||!b||!a.geometryVerified||!b.geometryVerified)throw Error('MISSING_SOURCE');const vd=verts(i,new T.Matrix4().fromArray(a.matrices.currentVessel)),vu=verts(i,new T.Matrix4().fromArray(b.matrices.currentVessel)),maxMove=Math.max(...vd.map((v,j)=>v.distanceTo(vu[j])));records.push({node:i,geometryDigest:a.originalGeometryDigest,positionAccessor:a.positionAccessor,indexAccessor:a.indexAccessor,sourceParentChain:a.parentChain.map(p=>({uuid:p.uuid,name:p.name})),downBounds:box(vd),upBounds:box(vu),maxVertexTravelM:maxMove,collisionRepresentation:a.collisionPolicy.policy,physicalThicknessKnown:a.collisionPolicy.physicalThicknessKnown,scope:'actual original vertices under captured endpoint transforms; bounds are descriptive, not a clearance oracle'});}
// All actual descendant vertices, not just the two implicated bolster meshes.
let radius=0;const descendantRows=[];for(let i=0;i<doc.nodes.length;i++){if(doc.nodes[i].mesh===undefined)continue;let p=i,root=null;while(parents.has(p)){p=parents.get(p);if(p===145||p===150){root=p;break;}}if(root!==null){const transform=rest(root).invert().multiply(rest(i)),r=Math.max(...verts(i,transform).map(v=>Math.hypot(v.x,v.y)));descendantRows.push({node:i,pivot:root,radiusM:r});radius=Math.max(radius,r);}}
const witness=down.knownH6WitnessCurrentH4,point=new T.Vector3().fromArray(witness.skin.vessel),g=geometry(138),fixed=verts(138,new T.Matrix4().fromArray(down.sources.find(s=>s.originalNodeIndex===138).matrices.currentVessel));let best={distance:Infinity};const triangles=[];for(let j=0;j<g.indices.length;j+=3){const t=new T.Triangle(...g.indices.slice(j,j+3).map(i=>fixed[i]));triangles.push(t);const q=t.closestPointToPoint(point,new T.Vector3()),d=q.distanceTo(point);if(d<best.distance)best={distance:d,triangle:j/3,point:q.toArray(),barycentric:t.getBarycoord(q,new T.Vector3()).toArray()};}
function hits(direction){const ray=new T.Ray(point,new T.Vector3(...direction).normalize()),out=[];for(const t of triangles){const h=ray.intersectTriangle(t.a,t.b,t.c,false,new T.Vector3());if(h)out.push(h.distanceTo(point));}out.sort((a,b)=>a-b);return out.filter((d,i)=>i===0||Math.abs(d-out[i-1])>1e-7);}
const rays=[[1,.371,.129],[-.193,1,.271],[.217,-.331,1]].map(d=>({direction:d,distancesM:hits(d)}));if(!rays.every(r=>r.distancesM.length%2===1)||best.distance<.05)throw Error('OBSTRUCTION_NOT_REPRODUCED');
// No fit search: invariance of this actual source across the entire existing
// linked-bolster degree of freedom. No alternate skin pose is manufactured.
const sweeps=Array.from({length:18},(_,i)=>{const degrees=i*5,m=rest(138,degrees*Math.PI/180),delta=Math.max(...m.elements.map((v,k)=>Math.abs(v-rest(138).elements[k])));if(delta>1e-12)throw Error('FIXED_SOURCE_MOVED');return {bolsterDegrees:degrees,fixed138MatrixDelta:delta,sameCapturedPoseInteriorDistanceM:best.distance};});
const origins=Object.fromEntries(contacts.contacts.map(c=>[c.id,new T.Vector3().setFromMatrixPosition(new T.Matrix4().fromArray(c.restContactToVessel))]));
const supports={seatOriginM:origins.seat.toArray(),leftFootOriginM:origins.leftFoot.toArray(),rightFootOriginM:origins.rightFoot.toArray(),seatToFootVerticalDropM:origins.seat.y-origins.leftFoot.y,seatToFootForwardM:origins.leftFoot.x-origins.seat.x,footLateralSeparationM:origins.rightFoot.z-origins.leftFoot.z,seatToHandDistancesM:[origins.seat.distanceTo(origins.leftHand),origins.seat.distanceTo(origins.rightHand)],seatHalfExtentsM:contacts.contacts.find(c=>c.id==='seat').finitePatch.halfExtentsM,footHalfExtentsM:contacts.contacts.find(c=>c.id==='leftFoot').finitePatch.halfExtentsM,handHalfExtentsM:contacts.contacts.find(c=>c.id==='leftHand').finitePatch.halfExtentsM,scope:'surface-center separations only; not anatomical arm lengths or reach acceptance'};
console.log(JSON.stringify({modelSHA256:hash(raw),snapshotHashes:{down:hash(fs.readFileSync(downPath)),up:hash(fs.readFileSync(upPath))},sourceSetSHA256:hash(fs.readFileSync(path.join(site,'c2-h6-source-set.json'))),contactSHA256:hash(fs.readFileSync(path.join(site,'c2-contacts.json'))),records,descendantRows,maxBolsterRadiusM:radius,maxEndpointSnapDisplacementM:2*radius*Math.sin(1e-5*Math.PI*85/180/2),capturedAvatarEnvelope:down.avatar.actualVesselAABB,indexedSkinCount:down.avatar.indexedVertexCount,obstruction:{capturedSkin:witness.skin,independentlyNearest:best,rays,scope:'source geometry requery conditional on actual captured H4 skin point; no new skin solve or H6 whole-body rerun'},existingMechanicalScan:sweeps,supports},null,2));
'''
data=json.loads(subprocess.check_output(['node','-e',program,str(SITE),str(down),str(up)],text=True))
assert data['maxEndpointSnapDisplacementM']<3.534e-6
fixed=[r for r in data['records'] if r['node'] in [138,137,81,139]];assert all(r['maxVertexTravelM']<1e-10 for r in fixed)
data.update({'revision':'core-bay-station-feasibility/settlement-02','sourceSHA':os.environ['GITHUB_SHA'],'device':DEV,'assessmentCompleted':True,'feasibleExistingConfigurationFound':False,'decision':'STATION_REVISION_REQUIRED_FOR_PINNED_H4_SUPPORT_RECIPE; KEEP_GAMEPLAY_UNAVAILABLE','mechanicalScope':'Only original mechanically exposed linked bolster travel0..85deg; no seat track, lift or footrest adjustment exists in current host. Endpoint/down-support contracts considered together. The continuously invariant node138 obstruction rules out this exact captured H4 pose at all bolster angles, not every possible human pose. No new fit attempted.','H6ConstraintReference':{'source':'417a3f86656c3e4094453a5dae9476a4e9cdc983','reportedFailures':61,'reportedMaxDepthM':.068095,'sixLiftAlternatives':'All failed joint/sole gates; referenced owner evidence, not rerun or republished as new fits'},'constraintDecisionTable':[{'constraint':'Cushion and both soles together','measurement':data['supports'],'result':'Exact five-patch support recipe retained; selected support is necessary but not sufficient'},{'constraint':'Fixed obstruction138 across legal mechanical DOF','measurementM':data['obstruction']['independentlyNearest']['distance'],'result':'FAIL for captured pinned H4 pose at both endpoints and entire intervening linked-hinge path; no amount of bolster rotation moves this source'},{'constraint':'Move147/148 without altering138/137/81/139','measurement':[{k:r[k] for k in ['node','maxVertexTravelM']} for r in data['records']],'result':'Mechanism moves only bolster descendants; up is not an approved alternative occupied pose'},{'constraint':'Full steering within same contact recipe','measurementRad':{'ownerLimited':.1,'hostTravel':3.3},'result':'UNAVAILABLE beyond H4 bound; separate H5 decision not adopted'},{'constraint':'Solid and sheet collision thickness','measurement':{'completeOriginalSets':33,'incompleteSheetSets':28,'diagnosticSheetThicknessM':0,'physicalSheetThicknessM':None},'result':'Full volumetric clearance cannot be approved without physical/proxy semantics'},{'constraint':'Avatar envelope','measurement':data['capturedAvatarEnvelope'],'result':'Descriptive only; not an AABB-derived feasibility verdict'}], 'unresolvedDesignInputs':[{'id':'SEAT_LOAD_BEARING_VOLUME','sources':[138,137,139,81],'required':'A specified load-bearing station redesign or adjustable mechanism with exact dimensions/attachment path that removes the node138 thigh conflict while preserving a finite seat top and both-foot support. Current 160mm node138 geometric bounding height is NOT inferred material thickness, and cutting it away solely around a skin witness is not approved.'},{'id':'COUPLED_SEAT_FOOT_HELM_LAYOUT','sources':[139,15,199,147,148],'required':'Select joint seat height/depth, both foot-support levels/extents and helm position/travel under the retained 1.93m avatar requirement, with exact source revision. Fixed center drop/forward/reach numbers in supports are design constraints, not fitted limb lengths. No unsupported seat lift, standing swap or contact widening is authorized.'},{'id':'PHYSICAL_PROXY_THICKNESS','required':'Source/component-bound volumetric or finite-thickness proxy for28 incomplete sets, especially the wheel. Thickness must be deliberately authored and reviewed; raw rendering sheets are currently0m diagnostic barriers with physical thickness unavailable.'},{'id':'BODY_CONTACT_AND_RECEIVING_RECIPE','required':'Source-bound permitted garment/body contacts and swept/articulation bounds for the chosen station, then separate exact HUMANS profile/ACK. Existing H4 ACK does not authorize new geometry, full steering, H5 or H7.'}],'newGeometrySelected':False,'newHumanFitPerformed':False,'physicalContactBoundsRelaxed':False,'publicActivation':False,'fullBodyAccepted':False})
raw=(json.dumps(data,indent=2)+'\n').encode();(OUT/'feasibility.json').write_bytes(raw);print(json.dumps({'assessmentCompleted':True,'feasible':False,'decision':data['decision'],'fixedWitnessM':data['obstruction']['independentlyNearest']['distance'],'snapDisplacementBoundM':data['maxEndpointSnapDisplacementM'],'fileSHA256':hashlib.sha256(raw).hexdigest()},indent=2))
